"""Render Figures 2–5 from CSVs generated by the study runner."""

import argparse
import json
from pathlib import Path
import warnings

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

from inputs import DATASETS
from studies import PERTURBATIONS, SCALE_COMPARISON_BUDGETS, SCALE_RATER_BUDGETS


METHODS = {
    "crowd_bt": ("Crowd-BT", "#E69F00", "s"),
    "bayes_bt": ("Bayes-BT", "#56B4E9", "^"),
    "bbq": ("BBQ", "#009E73", "v"),
    "label_smoothing": ("Label Smoothing (ε = 0.10)", "#CC79A7", "D"),
    "m_elo": ("m-ELO", "#0072B2", "x"),
    "am_elo": ("am-ELO", "#8B5A2B", "+"),
    "repair": ("RePair", "#D55E00", "o"),
}


def metric_lines(ax, frame, x, metric, *, scale=1, interval=False):
    for method, (label, color, marker) in METHODS.items():
        rows = frame.loc[frame["method"].eq(method)]
        if rows.empty:
            continue
        values = rows.groupby(x)[metric].agg(["mean", "std", "count"]).sort_index()
        positions = values.index.to_numpy(dtype=float)
        mean = values["mean"].to_numpy() * scale
        ax.plot(positions, mean, color=color, marker=marker, label=label,
                linewidth=2 if method == "repair" else 1.2, markersize=4)
        if interval:
            half = (1.96 * values["std"].fillna(0) / np.sqrt(values["count"]) * scale).to_numpy()
            ax.fill_between(positions, np.clip(mean - half, -1 if scale == 1 else 0, scale),
                            np.clip(mean + half, -1 if scale == 1 else 0, scale),
                            color=color, alpha=0.12)


def finish(fig, axes, output, legend=True):
    if legend:
        handles = {}
        for ax in axes.flat:
            for handle, label in zip(*ax.get_legend_handles_labels()):
                handles.setdefault(label, handle)
        if handles:
            fig.legend(handles.values(), handles.keys(), loc="lower center", ncol=min(4, len(handles)),
                       frameon=False)
        fig.tight_layout(rect=(0, 0.10, 1, 1))
    else:
        fig.tight_layout()
    fig.savefig(output, bbox_inches="tight")
    plt.close(fig)


def figure2(rows, output):
    fig, axes = plt.subplots(2, 4, figsize=(13, 5.4), sharex=True)
    rows = rows[rows["dataset"].isin(DATASETS[:6]) & rows["method"].ne("am_elo")].copy()
    dataset_count = rows["dataset"].nunique()
    rows["percent"] = rows["budget"] * 100
    # First average repetitions within each dataset. The second mean gives each
    # dataset equal weight even when valid fits differ in number.
    keys = ["axis", "condition", "method", "percent"]
    rows = rows.groupby(keys + ["dataset"], as_index=False)["kendall"].mean().dropna()
    rows = rows.groupby(keys, as_index=False).agg(kendall=("kendall", "mean"),
                                                  datasets=("dataset", "nunique"))
    rows = rows[rows["datasets"].eq(dataset_count)]
    for column, kind in enumerate(PERTURBATIONS):
        for row, (unit, label) in enumerate((("comparison", "Comparison-level"), ("rater", "Rater-level"))):
            ax = axes[row, column]
            mask = rows["axis"].eq(unit) & rows["condition"].eq(kind)
            metric_lines(ax, rows[mask], "percent", "kendall")
            ax.grid(alpha=0.24)
            if row == 0:
                ax.set_title(kind.capitalize())
            if column == 0:
                ax.set_ylabel(f"{label}\nMean Kendall’s τ")
            if row == 1:
                ax.set_xlabel("Selected labels (%)")
    finish(fig, axes, output)


def figure3(rows, output):
    fig, axes = plt.subplots(2, 4, figsize=(13, 5.4), sharex=True)
    rows = rows.loc[rows["dataset"].eq("ihq_all") & rows["axis"].eq("rater")].copy()
    rows["percent"] = rows["budget"] * 100
    for column, kind in enumerate(PERTURBATIONS):
        top, bottom = axes[:, column]
        part = rows.loc[rows["condition"].eq(kind)]
        metric_lines(top, part, "percent", "kendall")
        top.set_title(kind.capitalize())
        repair_rows = part.loc[part["method"].eq("repair")]
        rng = np.random.default_rng(20260814 + sum(map(ord, "ihq_all")) + column)
        if "rater_reliability" in repair_rows and repair_rows["rater_reliability"].notna().any():
            # The same clean fit supplies every zero-percent trial.
            clean = repair_rows.loc[repair_rows["percent"].eq(0)].head(1)
            repair_rows = pd.concat([clean, repair_rows.loc[repair_rows["percent"].ne(0)]])
            scores = [(row.percent, json.loads(row.rater_reliability))
                      for row in repair_rows.dropna(subset=["rater_reliability"]).itertuples()]
            for group, color in (("unpolluted", "#0072B2"), ("polluted", "#D55E00")):
                positions, reliability = [], []
                for level, record in scores:
                    estimates = record[group]
                    positions.extend(level + rng.uniform(-0.6, 0.6, size=len(estimates)))
                    reliability.extend(estimates)
                if reliability:
                    bottom.scatter(positions, reliability, color=color, s=5, alpha=0.26,
                                   rasterized=True, label=f"{group.capitalize()} raters")
        else:
            fields = ["unpolluted_reliability", "polluted_reliability"]
            quality = repair_rows.groupby("percent")[fields].mean()
            for field, label, color in zip(fields, ("Unpolluted raters", "Polluted raters"),
                                           ("#0072B2", "#D55E00")):
                estimable = quality[field].dropna()
                if not estimable.empty:
                    bottom.plot(estimable.index, estimable, color=color, marker="o", label=label)
        bottom.set_ylim(0, 1)
        bottom.set_xlabel("Selected labels (%)")
        top.grid(alpha=0.24)
        bottom.grid(alpha=0.24)
    axes[0, 0].set_ylabel("Kendall’s τ")
    axes[1, 0].set_ylabel("Estimated reliability")
    finish(fig, axes, output)


def figure4(rows, output):
    fig, axes = plt.subplots(2, 2, figsize=(8.2, 6.5), sharex="col")
    rows = rows.loc[rows["dataset"].eq("ihq_all") & rows["method"].ne("am_elo")].copy()
    for column, (axis, grid, label) in enumerate((
        ("n_raters", SCALE_RATER_BUDGETS, "Number of raters"),
        ("comparisons_per_rater", SCALE_COMPARISON_BUDGETS, "Comparisons per rater"),
    )):
        part = rows.loc[rows["axis"].eq(axis) & rows["budget"].isin(grid)].copy()
        part["position"] = part["budget"].map({budget: i for i, budget in enumerate(grid)})
        metric_lines(axes[0, column], part, "position", "top1", scale=100, interval=True)
        metric_lines(axes[1, column], part, "position", "kendall", interval=True)
        axes[0, column].set_ylim(0, 105)
        axes[1, column].set_xticks(range(len(grid)), [str(budget) for budget in grid])
        axes[1, column].set_xlabel(label)
        for ax in axes[:, column]:
            ax.grid(alpha=0.24)
    axes[0, 0].set_ylabel("Top-1 Agreement (%)")
    axes[1, 0].set_ylabel("Kendall’s τ")
    finish(fig, axes, output)


def pearson_interval(x, y, seed):
    rng = np.random.default_rng(seed)
    draws = rng.integers(len(x), size=(10_000, len(x)))
    x, y = x[draws], y[draws]
    x -= x.mean(axis=1, keepdims=True)
    y -= y.mean(axis=1, keepdims=True)
    with np.errstate(invalid="ignore", divide="ignore"):
        r = (x * y).sum(axis=1) / np.sqrt((x * x).sum(axis=1) * (y * y).sum(axis=1))
    finite = r[np.isfinite(r)]
    return np.quantile(finite, [0.025, 0.975]) if len(finite) else (float("nan"),) * 2


def figure5(rows, output):
    fig, axes = plt.subplots(1, 1, figsize=(5.7, 4.5), squeeze=False)
    ax = axes[0, 0]
    rows = rows.loc[rows["dataset"].eq("ihq_all") & rows["method"].eq("repair")]
    groups = (("screened", "#0072B2", "o"), ("unscreened", "#D55E00", "^"))
    seeds = np.random.SeedSequence(20260810).spawn(5)[2:4]
    for (group, color, marker), seed in zip(groups, seeds):
        part = rows.loc[rows["group"].eq(group)].dropna(subset=["agreement", "reliability"])
        x = part["agreement"].to_numpy(dtype=float)
        y = part["reliability"].to_numpy(dtype=float)
        if not len(x):
            continue
        label = f"IHQ-{group}\nMean agreement = {x.mean():.3f}, n = {len(x)}"
        if len(x) > 2 and np.ptp(x) > 0 and np.ptp(y) > 0:
            lo, hi = pearson_interval(x, y, seed)
            label += f"\nPearson r = {np.corrcoef(x, y)[0, 1]:.3f} [{lo:.3f}, {hi:.3f}]"
        ax.scatter(x, y, color=color, marker=marker, alpha=0.72, label=label)
    ax.set_xlabel("Agreement with final ranking")
    ax.set_ylabel("Estimated annotator reliability")
    if ax.has_data():
        ax.legend(loc="best", fontsize=8)
    ax.grid(alpha=0.24)
    finish(fig, axes, output, legend=False)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("inputs", nargs="+", type=Path, help="CSV files from the study runner")
    parser.add_argument("--output-dir", required=True, type=Path, help="Destination for generated figures")
    parser.add_argument("--format", choices=("pdf", "png"), default="pdf")
    args = parser.parse_args()
    rows = pd.concat([pd.read_csv(path) for path in args.inputs], ignore_index=True)
    if "study" not in rows or "status" not in rows:
        parser.error("Input CSVs must contain study and status columns")
    successful = rows[rows["status"].eq("ok") | rows["status"].eq("success")]
    figures = ((2, "perturbation", figure2), (3, "perturbation", figure3),
               (4, "scaling", figure4), (5, "consensus", figure5))
    args.output_dir.mkdir(parents=True, exist_ok=True)
    for number, study, render in figures:
        subset = successful[successful["study"].eq(study)]
        if subset.empty:
            continue
        if number == 3 and not (subset["dataset"].eq("ihq_all") & subset["axis"].eq("rater")).any():
            continue
        if number == 2 and set(subset["dataset"]) < set(DATASETS[:6]):
            warnings.warn("Figure 2 averages the available datasets. The paper uses six.", stacklevel=2)
        render(subset, args.output_dir / f"figure_{number}.{args.format}")


if __name__ == "__main__":
    main()
